syntax = "proto3";
package signaling.v1;

service Signaling {
  // Bidirectional rendezvous: client registers, then trickles
  // Offer/Answer + ICE. Server routes by stream_id.
  rpc Session(stream SessionMsg) returns (stream SessionMsg);
  // Short-lived TURN credentials; never hardcode shared secrets.
  rpc GetIceServers(GetIceServersReq) returns (GetIceServersResp);
}

message SessionMsg {
  string session_id = 1;
  string stream_id = 2;   // e.g. /project/device/front-camera
  oneof payload {
    SdpOffer offer = 3;
    SdpAnswer answer = 4;
    IceCandidate candidate = 5;
    Keepalive ping = 6;
    Hangup hangup = 7;
  }
}
message SdpOffer { string sdp = 1; string required_codec = 2; }
message SdpAnswer { string sdp = 1; string selected_codec = 2; }
message IceCandidate { string candidate = 1; string sdp_mid = 2; int32 mline = 3; }
message Keepalive { int64 client_ts_ms = 1; }
message Hangup { string reason = 1; }
message GetIceServersReq { string session_id = 1; }
message GetIceServersResp { repeated IceServer servers = 1; int64 ttl_seconds = 2; }
message IceServer { repeated string urls = 1; string username = 2; string credential = 3; }

// gRPC-Web stream carries signaling; RTCPeerConnection carries media.
const pc = new RTCPeerConnection({ iceServers: await getIceServers() });
pc.ontrack = (e) => { videoEl.srcObject = e.streams[0]; };
pc.onicecandidate = (e) => {
  if (e.candidate) signal.send({ candidate: toProto(e.candidate) });
};
// Media liveness independent of gRPC keepalive.
pc.addEventListener('connectionstatechange', () => {
  if (pc.connectionState === 'failed') signal.send({ restartIce: true });
});
const offer = await pc.createOffer({ offerToReceiveVideo: true });
await pc.setLocalDescription(offer);
signal.send({ offer: { sdp: offer.sdp, required_codec: 'H264' } });
signal.onMessage = async (msg) => {
  if (msg.answer) await pc.setRemoteDescription({ type: 'answer', sdp: msg.answer.sdp });
  if (msg.candidate) await pc.addIceCandidate(fromProto(msg.candidate));
};
